import{bQ as s,aL as a,u as t,G as i}from"./chunks/framework.DaEK0KQB.js";const k=JSON.parse('{"title":"Vite Proxy、Node 代理环境变量与 Clash 分流不生效问题排查","description":"","frontmatter":{"date":"2026-08-18T14:18:38.000Z","title":"Vite Proxy、Node 代理环境变量与 Clash 分流不生效问题排查","permalink":"/pages/7fa924","categories":["更多","服务器实例","VPN"]},"headers":[],"relativePath":"更多/服务器实例/05.Vite Proxy、Node 代理环境变量与 Clash 分流不生效问题排查.md","filePath":"更多/服务器实例/05.Vite Proxy、Node 代理环境变量与 Clash 分流不生效问题排查.md","lastUpdated":1787641541000}'),d={name:"更多/服务器实例/05.Vite Proxy、Node 代理环境变量与 Clash 分流不生效问题排查.md"};function n(o,e,l,p,r,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="vite-proxy、node-代理环境变量与-clash-分流不生效问题排查" tabindex="-1">Vite Proxy、Node 代理环境变量与 Clash 分流不生效问题排查 <a class="header-anchor" href="#vite-proxy、node-代理环境变量与-clash-分流不生效问题排查" aria-label="Permalink to &quot;Vite Proxy、Node 代理环境变量与 Clash 分流不生效问题排查&quot;">​</a></h1><p>本文记录本仓库联调 <code>http://192.200.125.79:9097</code> 时的实机结论。开发机：macOS + Clash Verge（系统代理开、TUN 关）+ Node <code>24.19.0</code> + <code>pnpm dev</code>（Vite <code>:3333</code>）。</p><h2 id="一、现象" tabindex="-1">一、现象 <a class="header-anchor" href="#一、现象" aria-label="Permalink to &quot;一、现象&quot;">​</a></h2><ul><li>浏览器打开 <code>http://localhost:3333/obd/api/sys/captchaImage</code> 有时正常。</li><li><code>http://localhost:3333/obd/api/sys/publicKey</code> 一直 pending / 超时。</li><li>Clash 已配规则脚本：</li></ul><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;IP-CIDR,192.200.125.0/24,DIRECT,no-resolve&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>Clash「代理绕过」已加 <code>192.200.125.0/24</code> 或 <code>192.200.125.79</code>。</li><li><code>~/.zshrc</code> 已配 <code>NO_PROXY=...,192.200.125.79</code>，同一终端 <code>echo $NO_PROXY</code> 也能看到。</li><li><strong>给 Vite <code>/obd</code> 配直连 <code>http.Agent</code>（<code>proxyEnv: {}</code>）后立刻正常。</strong></li></ul><p>根因不是「Clash 规则写错了」，而是：<strong>浏览器、Clash 规则、Node/Vite 出站不是同一条代理链路。</strong></p><hr><h2 id="二、实际请求链路" tabindex="-1">二、实际请求链路 <a class="header-anchor" href="#二、实际请求链路" aria-label="Permalink to &quot;二、实际请求链路&quot;">​</a></h2><p>登录页 axios 的 <code>VITE_OBD_BASE_URL=/obd</code>，浏览器只打本机：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器  →  localhost:3333/obd/...  →  Vite Dev Server</span></span>
<span class="line"><span>                                      （Node http.request）</span></span>
<span class="line"><span>                                      →  192.200.125.79:9097/obd/...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><table tabindex="0"><thead><tr><th>角色</th><th>看什么</th></tr></thead><tbody><tr><td>浏览器访问 <code>localhost:3333</code></td><td>macOS 系统代理 + Clash「代理绕过」（<code>ExceptionsList</code>）</td></tr><tr><td>浏览器直接打开 <code>http://192.200.125.79:9097/...</code></td><td>同上</td></tr><tr><td>Vite 转发 <code>/obd</code></td><td><strong>只认进程环境变量</strong> <code>HTTP_PROXY</code> / <code>NO_PROXY</code>，以及 <code>http.Agent</code>。<strong>不读</strong> Clash 规则，也<strong>不读</strong> macOS 绕过列表</td></tr></tbody></table><p>Clash 规则（<code>IP-CIDR ... DIRECT</code>）只处理 <strong>已经进到 Clash 里的包</strong>。Vite 若带着 <code>HTTP_PROXY=http://127.0.0.1:随机端口</code> 出站，会先打 Clash 的 HTTP 端口；端口失效（Clash 重启后端口会变）就会一直卡住，规则轮空。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有 HTTP_PROXY 且 Node 启用了环境代理：</span></span>
<span class="line"><span>  Vite → 127.0.0.1:Clash端口 →（此时才匹配规则）→ DIRECT / 代理节点</span></span>
<span class="line"><span></span></span>
<span class="line"><span>无 HTTP_PROXY，或 Agent.proxyEnv = {}：</span></span>
<span class="line"><span>  Vite → 192.200.125.79:9097    （根本不进 Clash，规则不执行）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="三、为什么-clash-配了还是不生效" tabindex="-1">三、为什么 Clash 配了还是不生效 <a class="header-anchor" href="#三、为什么-clash-配了还是不生效" aria-label="Permalink to &quot;三、为什么 Clash 配了还是不生效&quot;">​</a></h2><h3 id="_1-规则-绕过-no-proxy" tabindex="-1">1. 规则 ≠ 绕过 ≠ <code>NO_PROXY</code> <a class="header-anchor" href="#_1-规则-绕过-no-proxy" aria-label="Permalink to &quot;1. 规则 ≠ 绕过 ≠ \`NO_PROXY\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置</th><th>作用对象</th><th>对本仓库 Vite <code>/obd</code></th></tr></thead><tbody><tr><td><code>IP-CIDR,192.200.125.0/24,DIRECT</code></td><td>已进入 Clash 的流量</td><td><strong>不保证</strong> Node 不进 Clash</td></tr><tr><td>Clash「代理绕过」/ <code>system_proxy_bypass</code></td><td>macOS <code>ExceptionsList</code>（浏览器）</td><td>Node <strong>不看</strong></td></tr><tr><td><code>export NO_PROXY=...192.200.125.79</code></td><td>仅当 Node 启用了环境代理时</td><td>见下一节</td></tr></tbody></table><p><code>192.200.125.0/24</code> 不是 <code>192.168/10/172.16</code> 那种私网，Clash 默认「绕过局域网」管不到。</p><h3 id="_2-node-24-默认不看-no-proxy" tabindex="-1">2. Node 24 默认不看 <code>NO_PROXY</code> <a class="header-anchor" href="#_2-node-24-默认不看-no-proxy" aria-label="Permalink to &quot;2. Node 24 默认不看 \`NO_PROXY\`&quot;">​</a></h3><p>本机实测（Node <code>24.19.0</code>）：</p><table tabindex="0"><thead><tr><th>环境</th><th><code>http.request</code> 到 <code>192.200.125.79</code></th></tr></thead><tbody><tr><td>仅有 <code>HTTP_PROXY</code>，无 <code>NODE_USE_ENV_PROXY</code></td><td><strong>直连</strong>（不走代理，<code>NO_PROXY</code> 无意义）</td></tr><tr><td><code>NODE_USE_ENV_PROXY=1</code> + <code>HTTP_PROXY</code> + <code>NO_PROXY</code> 含该 IP</td><td>直连</td></tr><tr><td><code>NODE_USE_ENV_PROXY=1</code> + <code>HTTP_PROXY</code> + <code>NO_PROXY</code> 为空</td><td>打到 <code>127.0.0.1:代理端口</code></td></tr></tbody></table><p>因此：<strong>只在 zshrc 里写 <code>NO_PROXY</code>、不设 <code>NODE_USE_ENV_PROXY=1</code>，对 Vite 无效。</strong><br> Clash 也不会把「代理绕过」写进进程的 <code>NO_PROXY</code>（常见仍是 <code>127.0.0.1,::1,localhost</code>）。</p><p>Cursor / VS Code 从程序坞启动，<strong>不读 <code>~/.zshrc</code></strong>。必须在 <strong>即将执行 <code>pnpm dev</code> 的那个终端</strong> 里检查：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $HTTP_PROXY</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $NO_PROXY</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $NODE_USE_ENV_PROXY</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>改完 zshrc 或开关 Clash 系统代理后，要 <strong>完全退出编辑器再打开</strong>，旧窗口会一直带着启动时的变量。Clash 系统代理端口还会变（如 <code>53259</code> → <code>58389</code> → <code>10808</code>），旧 <code>pnpm dev</code> 连已死端口会表现为接口一直转圈。</p><h3 id="_3-vite-agent-的坑" tabindex="-1">3. Vite <code>agent</code> 的坑 <a class="header-anchor" href="#_3-vite-agent-的坑" aria-label="Permalink to &quot;3. Vite \`agent\` 的坑&quot;">​</a></h3><p>http-proxy-3 默认 <code>agent = options.agent \\|\\| false</code>。</p><table tabindex="0"><thead><tr><th>写法</th><th>结果</th></tr></thead><tbody><tr><td>不写 <code>agent</code> / <code>agent: false</code></td><td>每次新 Agent；是否走 <code>HTTP_PROXY</code> 取决于 Node 是否启用环境代理</td></tr><tr><td><code>proxyEnv: false</code> 或 <code>null</code></td><td>Node 24 <strong>会把请求卡死</strong>，不要用</td></tr><tr><td><code>new http.Agent({ proxyEnv: {} })</code></td><td>该 Agent <strong>不读</strong> <code>HTTP_PROXY</code>，本仓库已验证可通</td></tr></tbody></table><p><code>proxyOptions: { agent: false }</code> 不是 Vite 的合法字段，<strong>不会生效</strong>。</p><hr><h2 id="四、怎么确认卡在哪" tabindex="-1">四、怎么确认卡在哪 <a class="header-anchor" href="#四、怎么确认卡在哪" aria-label="Permalink to &quot;四、怎么确认卡在哪&quot;">​</a></h2><ol><li>终端（与 <code>pnpm dev</code> 同一窗口）：</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proxy</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $NODE_USE_ENV_PROXY</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ol start="2"><li>浏览器地址栏（不要用终端 curl 代替浏览器）：</li></ol><ul><li><code>http://127.0.0.1:3333/obd/api/sys/captchaImage?dt=1</code></li><li><code>http://127.0.0.1:3333/obd/api/sys/publicKey</code></li><li><code>http://192.200.125.79:9097/obd/api/sys/publicKey</code></li></ul><p>前两条走 Vite；第三条走浏览器系统代理。Vite 那条 pending、直连 9097 却很快，就是 Node 出站（<code>HTTP_PROXY</code> / 死端口）。两条都 pending，才是 9097 本身或网线（<code>en13</code> 到该网段）。</p><ol start="3"><li>curl 会认 macOS 系统代理，和 Node 不一致，排查时加 <code>--noproxy &#39;*&#39;</code>。</li></ol><hr><h2 id="五、本仓库现状-项目内已处理" tabindex="-1">五、本仓库现状（项目内已处理） <a class="header-anchor" href="#五、本仓库现状-项目内已处理" aria-label="Permalink to &quot;五、本仓库现状（项目内已处理）&quot;">​</a></h2><p><code>vite.config.ts</code> 中 <code>/obd</code> <strong>强制直连</strong>，不依赖本机 <code>NO_PROXY</code> 是否生效：</p><ul><li>启动时把 <code>192.200.125.79</code> 写入进程 <code>NO_PROXY</code> / <code>no_proxy</code></li><li><code>http.Agent({ keepAlive: true, timeout: 10000, proxyEnv: {} })</code></li><li><code>timeout</code> / <code>proxyTimeout</code>: 10000，避免无限 pending</li></ul><p>改 <code>vite.config.ts</code> 后必须重启 <code>pnpm dev</code>。</p><p>其它访问 <code>192.200.*</code> 的 <strong>Node</strong> 项目，若未做同样处理，在「系统代理开着」的机器上仍可能中招。浏览器直开该 IP 只看 Clash 绕过 / TUN。</p><hr><h2 id="六、不改项目、只改本机" tabindex="-1">六、不改项目、只改本机 <a class="header-anchor" href="#六、不改项目、只改本机" aria-label="Permalink to &quot;六、不改项目、只改本机&quot;">​</a></h2><p>按可靠性：</p><p><strong>1. 关系统代理 + 开 TUN（推荐）</strong></p><ul><li>Clash：关「系统代理」，开 TUN</li><li>保留规则：<code>IP-CIDR,192.200.125.0/24,DIRECT,no-resolve</code></li><li>TUN <code>route-exclude-address</code> 含 <code>192.200.125.0/24</code>（本机 Verge 已有）</li><li>完全退出 Cursor / VS Code 再开，再 <code>pnpm dev</code></li></ul><p>系统代理一关，就不会给 Node 注入 <code>HTTP_PROXY</code>。</p><p><strong>2. 启动时清掉代理（不改仓库）</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HTTP_PROXY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HTTPS_PROXY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL_PROXY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http_proxy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https_proxy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all_proxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>3. 让 Node 真的认 <code>NO_PROXY</code>（只写 NO_PROXY 不够）</strong></p><p><code>~/.zshrc</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NODE_USE_ENV_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NO_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;localhost,127.0.0.1,::1,192.200.125.79&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> no_proxy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$NO_PROXY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.zshrc</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 给 GUI 进程也带上（可选）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NO_PROXY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;localhost,127.0.0.1,::1,192.200.125.79&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>完全退出编辑器，<strong>新终端</strong>里确认 <code>$NO_PROXY</code> 含该 IP，且没被 Clash 覆盖成只有 <code>localhost</code>。</p><hr><h2 id="七、结论" tabindex="-1">七、结论 <a class="header-anchor" href="#七、结论" aria-label="Permalink to &quot;七、结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>实际</th></tr></thead><tbody><tr><td>Clash DIRECT 了，Vite 就会直连</td><td>Vite 可能根本没进 Clash，或卡在已死的本地代理端口</td></tr><tr><td>配了「代理绕过」Node 也会绕</td><td>那是给浏览器的；Node 只看环境变量 + Agent</td></tr><tr><td>zshrc 写了 <code>NO_PROXY</code> 就够</td><td>Node 24 还要 <code>NODE_USE_ENV_PROXY=1</code>，且编辑器要重开</td></tr><tr><td><code>agent: false</code> / <code>proxyOptions.agent</code></td><td>前者不一定关掉环境代理；后者 Vite 不认</td></tr><tr><td><code>proxyEnv: false</code></td><td>会卡死请求</td></tr></tbody></table><p><strong>Clash 管进入 Clash 的流量；Vite proxy 是 Node 自己的出站 HTTP。两套体系。</strong> 本仓库用直连 Agent 兜底；本机若关系统代理并开 TUN，其它 Node 项目也可少踩坑。</p>`,61)])])}const g=s(d,[["render",n]]);export{k as __pageData,g as default};
